--- index.html	
+++ index.html	
@@ -0,0 +1,257 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8" />
+<meta name="viewport" content="width=device-width, initial-scale=1.0" />
+<title>Neon Threader</title>
+<style>
+  :root { --bg:#070b18; --neon:#00f6ff; --pink:#ff2fb3; --gold:#ffd94d; }
+  * { box-sizing:border-box; margin:0; padding:0; }
+  body {
+    background:radial-gradient(1200px 800px at 50% -10%, #16204a 0%, var(--bg) 60%) fixed, var(--bg);
+    color:#e8f6ff; font-family:ui-sans-serif,system-ui,Segoe UI,Roboto,Helvetica,Arial;
+    min-height:100vh; display:flex; align-items:center; justify-content:center; padding:16px;
+  }
+  .wrap { width:min(720px,100%); }
+  header { display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; gap:12px; }
+  h1 { font-size:clamp(20px,3.5vw,28px); letter-spacing:.12em; text-transform:uppercase;
+    text-shadow:0 0 12px var(--neon),0 0 32px rgba(0,246,255,.5); }
+  h1 span { color:var(--pink); text-shadow:0 0 12px var(--pink); }
+  .hud { display:flex; gap:10px; }
+  .pill { background:rgba(255,255,255,.06); border:1px solid rgba(0,246,255,.35); border-radius:999px;
+    padding:6px 14px; font-variant-numeric:tabular-nums; font-weight:700; font-size:14px;
+    box-shadow:0 0 14px rgba(0,246,255,.15), inset 0 0 12px rgba(0,246,255,.08); white-space:nowrap; }
+  .arena { position:relative; border-radius:16px; overflow:hidden;
+    border:1px solid rgba(0,246,255,.4); box-shadow:0 0 30px rgba(0,246,255,.25),0 0 80px rgba(255,47,179,.15); }
+  canvas { display:block; width:100%; height:auto; aspect-ratio:4/3; background:#050816; touch-action:none; }
+  .overlay { position:absolute; inset:0; display:flex; flex-direction:column; align-items:center; justify-content:center;
+    text-align:center; gap:12px; padding:24px; background:rgba(4,6,16,.72); backdrop-filter:blur(4px); }
+  .overlay[hidden]{ display:none; }
+  .overlay h2 { font-size:clamp(26px,5vw,42px); letter-spacing:.1em; text-transform:uppercase;
+    text-shadow:0 0 16px var(--neon); }
+  .overlay p { max-width:44ch; line-height:1.5; color:#bcd6ea; font-size:clamp(13px,2.4vw,15px); }
+  kbd { background:#0e1630; border:1px solid rgba(255,255,255,.25); border-bottom-width:3px; border-radius:6px;
+    padding:1px 7px; font-family:inherit; font-size:.9em; }
+  .btn { cursor:pointer; border:none; border-radius:999px; padding:12px 28px; font-weight:800; letter-spacing:.08em;
+    text-transform:uppercase; color:#04121a; background:linear-gradient(90deg,var(--neon),#7dffcb);
+    box-shadow:0 0 22px rgba(0,246,255,.7); font-size:15px; }
+  .btn:active { transform:translateY(1px); }
+  footer { margin-top:10px; display:flex; justify-content:space-between; gap:10px; flex-wrap:wrap;
+    color:#8fa9c4; font-size:12.5px; }
+</style>
+</head>
+<body>
+<div class="wrap">
+  <header>
+    <h1>Neon <span>Threader</span></h1>
+    <div class="hud">
+      <div class="pill" id="score">Score 0</div>
+      <div class="pill" id="best">Best 0</div>
+    </div>
+  </header>
+  <div class="arena">
+    <canvas id="game" width="640" height="480"></canvas>
+    <div class="overlay" id="startScreen">
+      <h2>Neon Threader</h2>
+      <p>Pilot your glowing thread. Collect <b style="color:var(--gold)">energy sparks</b> for +10.
+      Avoid the <b style="color:var(--pink)">expanding pulse rings</b> — touching a ring ends the run.
+      Walls are deadly too.</p>
+      <p><kbd>WASD</kbd> / <kbd>←↑↓→</kbd> to steer &nbsp;•&nbsp; <kbd>Space</kbd> to start &nbsp;•&nbsp; <kbd>R</kbd> to restart &nbsp;•&nbsp; <kbd>P</kbd> to pause</p>
+      <button class="btn" id="startBtn">Start Threading</button>
+    </div>
+    <div class="overlay" id="overScreen" hidden>
+      <h2 style="text-shadow:0 0 16px var(--pink)">Thread Cut</h2>
+      <p id="finalLine">Score 0</p>
+      <p><kbd>R</kbd> / <kbd>Space</kbd> / click to thread again</p>
+      <button class="btn" id="restartBtn">Restart</button>
+    </div>
+  </div>
+  <footer>
+    <span>Tip: sparks speed you up slightly — rings spawn faster as you score.</span>
+    <span id="status">Ready</span>
+  </footer>
+</div>
+<script>
+(function(){
+  "use strict";
+  var W=640,H=480;
+  var canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+  var scoreEl=document.getElementById('score'),bestEl=document.getElementById('best');
+  var startScreen=document.getElementById('startScreen'),overScreen=document.getElementById('overScreen');
+  var finalLine=document.getElementById('finalLine'),statusEl=document.getElementById('status');
+
+  var state='start',score=0,best=+(localStorage.getItem('neon-threader-best')||0);
+  var player,trail,sparks,rings,particles,keys,lastTime,sparkTimer,ringTimer,speedMul,paused;
+
+  function reset(){
+    player={x:W/2,y:H/2,vx:160,vy:0,dir:0,r:6};
+    trail=[];sparks=[];rings=[];particles=[];score=0;speedMul=1;paused=false;
+    sparkTimer=0;ringTimer=1.2;lastTime=performance.now();
+    for(var i=0;i<4;i++)spawnSpark();
+    updateHud();
+  }
+  function updateHud(){scoreEl.textContent='Score '+score;bestEl.textContent='Best '+best;}
+  function rand(a,b){return a+Math.random()*(b-a);}
+  function spawnSpark(){
+    for(var t=0;t<20;t++){
+      var p={x:rand(30,W-30),y:rand(30,H-30),r:7,pulse:rand(0,6)};
+      var bad=rings.some(function(r){return Math.hypot(p.x-r.x,p.y-r.y)<r.r+30;});
+      if(!bad&&Math.hypot(p.x-player.x,p.y-player.y)>60){sparks.push(p);return;}
+    }
+    sparks.push({x:rand(30,W-30),y:rand(30,H-30),r:7,pulse:0});
+  }
+  function spawnRing(){
+    var edge=Math.floor(rand(0,4)),x,y;
+    if(edge===0){x=rand(60,W-60);y=50;}else if(edge===1){x=rand(60,W-60);y=H-50;}
+    else if(edge===2){x=50;y=rand(60,H-60);}else{x=W-50;y=rand(60,H-60);}
+    // bias away from player so spawn is fair
+    if(Math.hypot(x-player.x,y-player.y)<140){x=W-x;y=H-y;}
+    rings.push({x:x,y:y,r:8,maxR:rand(150,240),speed:rand(70,110)+score*0.6,thick:9,life:0});
+  }
+  function burst(x,y,color,n){
+    for(var i=0;i<(n||14);i++)particles.push({x:x,y:y,vx:rand(-160,160),vy:rand(-160,160),life:rand(.3,.7),t:0,color:color});
+  }
+  function setState(s){
+    state=s;
+    startScreen.hidden=(s!=='start');
+    overScreen.hidden=(s!=='over');
+    statusEl.textContent=s==='play'?'Threading…':s==='over'?'Game over':s==='pause'?'Paused':'Ready';
+  }
+  function startGame(){reset();setState('play');requestAnimationFrame(loop);}
+  function gameOver(){
+    setState('over');
+    best=Math.max(best,score);
+    localStorage.setItem('neon-threader-best',best);updateHud();
+    finalLine.textContent='You scored '+score+' — best '+best+'.';
+    burst(player.x,player.y,'#ff2fb3',40);
+  }
+
+  keys={};
+  addEventListener('keydown',function(e){
+    var k=e.key.toLowerCase();
+    if(['arrowup','arrowdown','arrowleft','arrowright',' '].indexOf(k)>=0||k===' ')e.preventDefault();
+    keys[k]=true;
+    if(k===' '||k==='enter'){if(state==='start'||state==='over')startGame();}
+    if(k==='r'){if(state==='play'||state==='over'||state==='pause')startGame();}
+    if(k==='p'&&state==='play'){state='pause';setState('pause');}
+    else if(k==='p'&&state==='pause'){setState('play');lastTime=performance.now();requestAnimationFrame(loop);}
+  });
+  addEventListener('keyup',function(e){keys[e.key.toLowerCase()]=false;});
+  document.getElementById('startBtn').addEventListener('click',startGame);
+  document.getElementById('restartBtn').addEventListener('click',startGame);
+  overScreen.addEventListener('click',function(e){if(e.target.id!=='restartBtn')startGame();});
+
+  // touch: steer toward touch point
+  var touch=null;
+  canvas.addEventListener('pointerdown',function(e){
+    if(state==='start'||state==='over'){startGame();return;}
+    touch=point(e);
+  });
+  canvas.addEventListener('pointermove',function(e){if(touch)touch=point(e);});
+  addEventListener('pointerup',function(){touch=null;});
+  function point(e){var r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H};}
+
+  var STEER=260,TURN=5.2;
+  function update(dt){
+    // steering: directional input sets target velocity
+    var ax=0,ay=0;
+    if(keys['arrowleft']||keys['a'])ax-=1; if(keys['arrowright']||keys['d'])ax+=1;
+    if(keys['arrowup']||keys['w'])ay-=1; if(keys['arrowdown']||keys['s'])ay+=1;
+    var sp=190*speedMul;
+    if(ax||ay){var m=Math.hypot(ax,ay);player.vx=ax/m*sp;player.vy=ay/m*sp;}
+    else if(touch){var dx=touch.x-player.x,dy=touch.y-player.y,d=Math.hypot(dx,dy)||1;player.vx=dx/d*sp;player.vy=dy/d*sp;}
+    else{ // keep momentum, gentle drift forward
+      var cur=Math.hypot(player.vx,player.vy)||1;player.vx=player.vx/cur*sp;player.vy=player.vy/cur*sp;
+    }
+    player.x+=player.vx*dt;player.y+=player.vy*dt;
+    trail.push({x:player.x,y:player.y});if(trail.length>70)trail.shift();
+
+    // walls
+    if(player.x<8||player.x>W-8||player.y<8||player.y>H-8){gameOver();return;}
+
+    // self-trail collision (skip recent segment)
+    for(var i=0;i<trail.length-25;i++){var t=trail[i];if(Math.hypot(player.x-t.x,player.y-t.y)<5){gameOver();return;}}
+
+    // sparks
+    sparkTimer-=dt;if(sparkTimer<=0&&sparks.length<6){spawnSpark();sparkTimer=.6;}
+    for(var s=sparks.length-1;s>=0;s--){var p=sparks[s];p.pulse+=dt*5;
+      if(Math.hypot(player.x-p.x,player.y-p.y)<player.r+p.r+2){
+        sparks.splice(s,1);score+=10;speedMul=Math.min(1.6,speedMul+0.02);
+        burst(p.x,p.y,'#ffd94d',14);spawnSpark();updateHud();
+      }
+    }
+    // rings
+    ringTimer-=dt;
+    var interval=Math.max(0.55,1.6-score*0.015);
+    if(ringTimer<=0){spawnRing();if(score>60)spawnRing();ringTimer=interval;}
+    for(var r=rings.length-1;r>=0;r--){var g=rings[r];g.r+=g.speed*dt;g.life+=dt;
+      var dist=Math.hypot(player.x-g.x,player.y-g.y);
+      if(Math.abs(dist-g.r)<g.thick/2+player.r-1){gameOver();return;}
+      if(g.r>=g.maxR)rings.splice(r,1);
+    }
+    // particles
+    for(var q=particles.length-1;q>=0;q--){var c=particles[q];c.t+=dt;
+      if(c.t>=c.life){particles.splice(q,1);continue;}c.x+=c.vx*dt;c.y+=c.vy*dt;}
+  }
+
+  function drawGrid(){
+    ctx.fillStyle='#050816';ctx.fillRect(0,0,W,H);
+    ctx.strokeStyle='rgba(0,246,255,.08)';ctx.lineWidth=1;ctx.beginPath();
+    for(var x=0;x<=W;x+=40){ctx.moveTo(x,0);ctx.lineTo(x,H);}
+    for(var y=0;y<=H;y+=40){ctx.moveTo(0,y);ctx.lineTo(W,y);}
+    ctx.stroke();
+    ctx.strokeStyle='rgba(0,246,255,.5)';ctx.lineWidth=2;
+    ctx.shadowColor='#00f6ff';ctx.shadowBlur=14;ctx.strokeRect(4,4,W-8,H-8);ctx.shadowBlur=0;
+  }
+  function draw(t){
+    drawGrid();
+    // sparks
+    sparks.forEach(function(p){
+      var tw=1+Math.sin(p.pulse)*0.15;
+      ctx.save();ctx.shadowColor='#ffd94d';ctx.shadowBlur=18;
+      ctx.fillStyle='#ffd94d';ctx.beginPath();ctx.arc(p.x,p.y,p.r*tw,0,7);ctx.fill();
+      ctx.fillStyle='#fff8d0';ctx.beginPath();ctx.arc(p.x,p.y,3*tw,0,7);ctx.fill();ctx.restore();
+    });
+    // rings
+    rings.forEach(function(g){
+      var alpha=1-g.r/g.maxR;
+      ctx.save();ctx.globalAlpha=Math.max(.15,alpha);
+      ctx.strokeStyle='#ff2fb3';ctx.lineWidth=g.thick;ctx.shadowColor='#ff2fb3';ctx.shadowBlur=22;
